package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeObject_TriageGen2Test {

    private KeyedObjects2D dataset;
    private final Comparable rowKey1 = "Row1";
    private final Comparable rowKey2 = "Row2";
    private final Comparable colKey1 = "Col1";
    private final Comparable colKey2 = "Col2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveObject_WhenRowBecomesEmpty_ShouldRemoveRowFromDataStructures() {
        // Arrange: Setup a row with only one object
        dataset.addObject("Value1", rowKey1, colKey1);

        // Verify initial state
        assertEquals(1, dataset.getRowCount());
        assertEquals("Value1", dataset.getObject(rowKey1, colKey1));

        // Act: Remove the only object in the row
        dataset.removeObject(rowKey1, colKey1);

        // Assert: Row should be removed from rowKeys and rows map
        // Since row is empty, getRowCount should be 0
        assertEquals(0, dataset.getRowCount());

        // Attempting to get row index for a removed row might throw exception or return -1 
        // depending on internal implementation, but based on the code logic:
        // if allNull is true, rowKeys.remove(rowIndex) occurs.
        List rowKeys = dataset.getRowKeys();
        boolean rowKeyExists = false;
        for (int i = 0; i < rowKeys.size(); i++) {
            if (rowKeys.get(i).equals(rowKey1)) {
                rowKeyExists = true;
                break;
            }
        }
        assertTrue("Row key should have been removed", !rowKeyExists);
    }

    @Test
    public void testRemoveObject_WhenRowIsNotEmpty_ShouldKeepRow() {
        // Arrange: Setup a row with two objects
        dataset.addObject("Value1", rowKey1, colKey1);
        dataset.addObject("Value2", rowKey1, colKey2);

        // Act: Remove only one object
        dataset.removeObject(rowKey1, colKey1);

        // Assert: Row should still exist because it contains "Value2"
        assertEquals(1, dataset.getRowCount());
        assertNull("Object at (rowKey1, colKey1) should be null", dataset.getObject(rowKey1, colKey1));
        assertEquals("Value2", dataset.getObject(rowKey1, colKey2));

        List rowKeys = dataset.getRowKeys();
        boolean rowKeyExists = false;
        for (int i = 0; i < rowKeys.size(); i++) {
            if (rowKeys.get(i).equals(rowKey1)) {
                rowKeyExists = true;
                break;
            }
        }
        assertTrue("Row key should still exist", rowKeyExists);
    }

    @Test
    public void testRemoveObject_WhenObjectIsAlreadyNull_ShouldNotChangeRowCount() {
        // Arrange: Setup row with one object and one null
        dataset.addObject("Value1", rowKey1, colKey1);
        dataset.setObject(null, rowKey1, colKey2);

        // Act: Remove the existing object
        dataset.removeObject(rowKey1, colKey1);

        // Assert: Row becomes empty and is removed
        assertEquals(0, dataset.getRowCount());
    }

    @Test
    public void testRemoveObject_OnNonExistentKeys() {
        // Arrange: Dataset is empty

        // Act & Assert: Should handle gracefully or throw based on implementation. 
        // Given the code provided, getRowIndex(rowKey) is called. 
        // If rowKey doesn't exist, getRowIndex likely returns -1 or throws.
        // If it returns -1, the subsequent rows.get(-1) would throw NullPointerException or IndexOutOfBounds.
        // However, we test the path where the object exists but we set it to null.

        dataset.addObject("Val", rowKey1, colKey1);
        dataset.removeObject(rowKey1, colKey1);
        assertEquals(0, dataset.getRowCount());
    }
}
